DO $$ DECLARE d text; name text; BEGIN FOREACH name IN ARRAY ARRAY['public.notification_claim()','public.notification_schedule_next()'] LOOP SELECT pg_get_functiondef(name::regprocedure) INTO d; d:=replace(d,'''pending'',''failed'',''awaiting_credentials''','''pending'',''failed'',''awaiting_credentials'',''partial'''); EXECUTE d; END LOOP; END; $$;
CREATE OR REPLACE FUNCTION notification_private.retry_notification(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.profiles; BEGIN
IF NOT public.is_notification_staff() OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_active) THEN RAISE EXCEPTION 'Staff access required'; END IF;
SELECT pr.* INTO p FROM public.profiles pr JOIN public.notification_outbox n ON n.user_id=pr.id WHERE n.id=p_id AND n.status IN ('failed','blocked','awaiting_credentials','partial'); IF NOT FOUND THEN RAISE EXCEPTION 'Not retryable'; END IF;
IF NOT EXISTS(SELECT 1 FROM (VALUES('email',lower(trim(coalesce(p.email,'')))),('text',regexp_replace(coalesce(p.phone,''),'[^+0-9]','','g'))) v(channel,contact) LEFT JOIN public.notification_contacts c ON c.channel=v.channel AND c.contact=v.contact WHERE v.contact<>'' AND coalesce(c.failures,0)<5 AND (p.notification_method='both' OR p.notification_method=v.channel) AND NOT EXISTS(SELECT 1 FROM public.notification_deliveries d WHERE d.notification_id=p_id AND d.channel=v.channel AND d.contact=v.contact AND d.status='sent')) THEN RAISE EXCEPTION 'Update blocked contact before retrying'; END IF;
UPDATE public.notification_outbox SET status='pending',next_attempt_at=now(),manual_retry=true WHERE id=p_id; END; $$;